import React, { useEffect, useState } from 'react';
import {
  fetchSchoolStudents,
  fetchSchoolStudentDetail,
  SchoolStudentItem,
  SchoolStudentSummary
} from '../api';

const SchoolStudents: React.FC = () => {
  const [students, setStudents] = useState<SchoolStudentItem[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [detail, setDetail] = useState<SchoolStudentSummary | null>(null);

  useEffect(() => {
    fetchSchoolStudents().then((d) => setStudents(d.students));
  }, []);

  useEffect(() => {
    if (!selectedId) {
      setDetail(null);
      return;
    }
    fetchSchoolStudentDetail(selectedId).then(setDetail).catch(() => setDetail(null));
  }, [selectedId]);

  return (
    <div className="school-students">
      <h2>学生列表（脱敏）</h2>
      <div className="school-students-layout">
        <div className="school-card school-student-table-wrap">
          <table className="school-table">
            <thead>
              <tr>
                <th>学生</th>
                <th>咨询次数</th>
                <th>最近情绪</th>
                <th>风险</th>
                <th>待处理</th>
              </tr>
            </thead>
            <tbody>
              {students.map((s) => (
                <tr
                  key={s.id}
                  className={selectedId === s.id ? 'selected' : ''}
                  onClick={() => setSelectedId(s.id)}
                >
                  <td>{s.maskName}</td>
                  <td>{s.consultCount}</td>
                  <td>{s.lastEmotion || '—'}</td>
                  <td>{s.lastRisk || '—'}</td>
                  <td>{s.pendingAlerts > 0 ? s.pendingAlerts : '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {students.length === 0 && <p className="muted">暂无学生账号数据</p>}
        </div>

        <div className="school-card">
          {!detail && <p className="muted">点击左侧学生查看近期心理态势摘要</p>}
          {detail && (
            <>
              <h3>{detail.maskName}</h3>
              <p className="muted">机构：{detail.orgId}</p>
              <h4>近期咨询摘要</h4>
              {detail.timeline.length === 0 && <p className="muted">暂无咨询记录</p>}
              <ul className="school-timeline">
                {detail.timeline.map((t) => (
                  <li key={t.time}>
                    <strong>{new Date(t.time).toLocaleString('zh-CN')}</strong>
                    <span>
                      {t.emotion} · {t.problem} · 风险 {t.risk}
                      {t.stressLevel != null ? ` · 压力 ${t.stressLevel}` : ''}
                    </span>
                    <p>{t.summary}</p>
                  </li>
                ))}
              </ul>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default SchoolStudents;
